const j = $input.first().json;
// WhatsApp Trigger output (also tolerates the raw Meta payload shape)
const v = j.messages ? j : (j.value || j.body?.entry?.[0]?.changes?.[0]?.value);
const m = v?.messages?.[0];
if (!m) return [];   // delivery/read statuses etc. are ignored
let text = '';
if (m.type === 'text') text = m.text?.body || '';
else if (m.type === 'interactive') text = m.interactive?.button_reply?.title || m.interactive?.list_reply?.title || '';
if (!text) return [];
return [{ json: { from: String(m.from), name: v.contacts?.[0]?.profile?.name || '', text, message_id: m.id } }];

